pport": true, "facts": ["docker", "docker_image", "compose"], "sources": ["https://docs.baby-buddy.net/setup/deployment/", "https://github.com/babybuddy/babybuddy", "https://github.com/linuxserver/docker-babybuddy", "https://hub.docker.com/r/linuxserver/babybuddy"], "options": [{"method": "docker", "label": "Baby Buddy LinuxServer container", "url": "https://hub.docker.com/r/linuxserver/babybuddy", "support_level": "community", "source_url": "https://docs.baby-buddy.net/setup/deployment/", "image": "lscr.io/linuxserver/babybuddy:latest", "note": "Baby Buddy's own docs recommend the LinuxServer.io community-maintained container.", "sort_order": 10}, {"method": "compose", "label": "Baby Buddy Docker Compose template", "url": "https://docs.baby-buddy.net/setup/deployment/", "support_level": "community", "source_url": "https://docs.baby-buddy.net/setup/deployment/", "image": "lscr.io/linuxserver/babybuddy:latest", "note": "The official deployment guide includes a Compose template using the LinuxServer.io community image.", "sort_order": 20}, {"method": "native", "label": "Baby Buddy manual server setup", "url": "https://docs.baby-buddy.net/setup/deployment/", "support_level": "official", "source_url": "https://docs.baby-buddy.net/setup/deployment/", "image": null, "note": "Official manual deployment guide.", "sort_order": 30}]}]
$review$::jsonb) AS x(
      id uuid,
      slug text,
      old_install_docs text,
      old_docker_url text,
      old_docker_image text,
      old_compose_url text,
      old_methods text[],
      old_docker_support text,
      old_compose_support boolean,
      old_docker_status text,
      old_image_status text,
      old_compose_status text,
      install_docs text,
      docker_url text,
      docker_image text,
      compose_url text,
      methods text[],
      docker_support text,
      compose_support boolean,
      facts text[],
      sources text[],
      options jsonb
    )
  LOOP
    UPDATE public.self_host_apps AS a
    SET install_docs_url = r.install_docs,
        docker_url = r.docker_url,
        docker_image = r.docker_image,
        compose_url = r.compose_url,
        deployment_methods = r.methods,
        docker_support = r.docker_support,
        compose_support = r.compose_support,
        data_source_urls = ARRAY(
          SELECT DISTINCT source_url
          FROM unnest(coalesce(a.data_source_urls, ARRAY[]::text[]) || r.sources) AS s(source_url)
          WHERE source_url IS NOT NULL
          ORDER BY source_url
        ),
        technical_fact_status =
          (
            coalesce(a.technical_fact_status, '{}'::jsonb)
            - ARRAY['docker', 'docker_image', 'compose']::text[]
          )
          || CASE WHEN 'docker' = ANY(r.facts) THEN jsonb_build_object(
            'docker', jsonb_build_object(
              'status', 'published',
              'checked_at', '2026-09-30',
              'confidence', 'high',
              'source_urls', ARRAY(
                SELECT DISTINCT source_url
                FROM unnest(ARRAY[r.install_docs, coalesce(r.docker_url, r.compose_url)]::text[]) AS s(source_url)
                WHERE source_url IS NOT NULL
                ORDER BY source_url
              )
            )
          ) ELSE '{}'::jsonb END
          || CASE WHEN 'docker_image' = ANY(r.facts) THEN jsonb_build_object(
            'docker_image', jsonb_build_object(
              'status', 'published',
              'checked_at', '2026-09-30',
              'confidence', 'high',
              'source_urls', ARRAY[r.docker_url]::text[]
            )
          ) ELSE '{}'::jsonb END
          || CASE WHEN 'compose' = ANY(r.facts) THEN jsonb_build_object(
            'compose', jsonb_build_object(
              'status', 'published',
              'checked_at', '2026-09-30',
              'confidence', 'high',
              'source_urls', ARRAY(
                SELECT DISTINCT source_url
                FROM unnest(ARRAY[r.install_docs, r.compose_url]::text[]) AS s(source_url)
                WHERE source_url IS NOT NULL
                ORDER BY source_url
              )
            )
          ) ELSE '{}'::jsonb END,
        updated_at = now()
    WHERE a.id = r.id
      AND a.slug = r.slug
      AND a.published IS NOT DISTINCT FROM TRUE
      AND a.self_hosting_status IS NOT DISTINCT FROM 'self_hostable'
      AND a.install_docs_url IS NOT DISTINCT FROM r.old_install_docs
      AND a.docker_url IS NOT DISTINCT FROM r.old_docker_url
      AND a.docker_image IS NOT DISTINCT FROM r.old_docker_image
      AND a.compose_url IS NOT DISTINCT FROM r.old_compose_url
      AND a.deployment_methods IS NOT DISTINCT FROM r.old_methods
      AND a.docker_support IS NOT DISTINCT FROM r.old_docker_support
      AND a.compose_support IS NOT DISTINCT FROM r.old_compose_support
      AND a.technical_fact_status->'docker'->>'status' IS NOT DISTINCT FROM r.old_docker_status
      AND a.technical_fact_status->'docker_image'->>'status' IS NOT DISTINCT FROM r.old_image_status
      AND a.technical_fact_status->'compose'->>'status' IS NOT DISTINCT FROM r.old_compose_status
      AND EXISTS (
        SELECT 1
        FROM public.self_host_app_install_options AS i
        WHERE i.app_id = a.id
          AND i.options IS NOT DISTINCT FROM '[]'::jsonb
          AND cardinality(coalesce(i.docker_images, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.docker_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.compose_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.truenas_scale_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.unraid_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.umbrel_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.yunohost_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.casaos_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.runtipi_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.cosmos_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.openmediavault_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.synology_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.qnap_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.proxmox_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.home_assistant_os_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.kubernetes_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.helm_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.native_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.binary_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.package_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.other_urls, ARRAY[]::text[])) = 0
          AND cardinality(coalesce(i.source_urls, ARRAY[]::text[])) = 0
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'App review guard failed for % (%)', r.slug, r.id;
    END IF;

    UPDATE public.self_host_app_install_options AS i
    SET options = r.options,
        source_urls = ARRAY(
          SELECT DISTINCT option->>'source_url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'source_url' IS NOT NULL
          ORDER BY option->>'source_url'
        ),
        docker_images = ARRAY(
          SELECT DISTINCT option->>'image'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'image' IS NOT NULL
          ORDER BY option->>'image'
        ),
        docker_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'docker'
          ORDER BY option->>'url'
        ),
        compose_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'compose'
          ORDER BY option->>'url'
        ),
        truenas_scale_urls = ARRAY[]::text[],
        unraid_urls = ARRAY[]::text[],
        umbrel_urls = ARRAY[]::text[],
        yunohost_urls = ARRAY[]::text[],
        casaos_urls = ARRAY[]::text[],
        runtipi_urls = ARRAY[]::text[],
        cosmos_urls = ARRAY[]::text[],
        openmediavault_urls = ARRAY[]::text[],
        synology_urls = ARRAY[]::text[],
        qnap_urls = ARRAY[]::text[],
        proxmox_urls = ARRAY[]::text[],
        home_assistant_os_urls = ARRAY[]::text[],
        kubernetes_urls = ARRAY[]::text[],
        helm_urls = ARRAY[]::text[],
        native_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'native'
          ORDER BY option->>'url'
        ),
        binary_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'binary'
          ORDER BY option->>'url'
        ),
        package_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'package'
          ORDER BY option->>'url'
        ),
        other_urls = ARRAY(
          SELECT DISTINCT option->>'url'
          FROM jsonb_array_elements(r.options) AS option
          WHERE option->>'method' = 'other'
          ORDER BY option->>'url'
        ),
        checked_at = DATE '2026-09-30',
        updated_at = now()
    WHERE i.app_id = r.id
      AND i.options IS NOT DISTINCT FROM '[]'::jsonb
      AND cardinality(coalesce(i.docker_images, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.docker_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.compose_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.truenas_scale_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.unraid_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.umbrel_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.yunohost_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.casaos_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.runtipi_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.cosmos_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.openmediavault_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.synology_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.qnap_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.proxmox_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.home_assistant_os_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.kubernetes_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.helm_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.native_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.binary_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.package_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.other_urls, ARRAY[]::text[])) = 0
      AND cardinality(coalesce(i.source_urls, ARRAY[]::text[])) = 0;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Install-option guard failed for % (%)', r.slug, r.id;
    END IF;

    v_rows := v_rows + 1;
  END LOOP;

  IF v_rows <> 23 THEN
    RAISE EXCEPTION 'Expected 23 reviewed apps; updated %', v_rows;
  END IF;
END $$;
